// dlqw002-read-and-diff (PRO-215)
// Poll /miru-data/dispatch_dlq.jsonl and emit only appended rows.
// State key: dlq_last_seen_line_count in workflow static data.
// First run seeds the baseline silently so historical DLQ rows do not replay.
const fs = require('fs');
const PATH = '/miru-data/dispatch_dlq.jsonl';
const STATE_KEY = 'dlq_last_seen_line_count';

const staticData = $getWorkflowStaticData('global');
let content = '';
if (fs.existsSync(PATH)) {
  content = fs.readFileSync(PATH, 'utf8');
}

const rows = content.split(/\r?\n/).filter(line => line.trim().length > 0);
const currentCount = rows.length;
const rawBaseline = staticData[STATE_KEY];
const hasBaseline = Number.isInteger(rawBaseline) || (typeof rawBaseline === 'number' && isFinite(rawBaseline) && Math.floor(rawBaseline) === rawBaseline);

if (!hasBaseline) {
  staticData[STATE_KEY] = currentCount;
  return [{ json: { new_rows: [], current_count: currentCount, last_seen_count: currentCount, _init: true } }];
}

const lastSeenCount = Number(rawBaseline);
if (currentCount <= lastSeenCount) {
  if (currentCount < lastSeenCount) {
    // Preserve idempotency if the file ever regresses or is truncated.
    staticData[STATE_KEY] = currentCount;
  }
  return [{ json: { new_rows: [], current_count: currentCount, last_seen_count: staticData[STATE_KEY], _init: false } }];
}

const newRows = rows.slice(lastSeenCount);
staticData[STATE_KEY] = currentCount;
return [{ json: { new_rows: newRows, current_count: currentCount, last_seen_count: lastSeenCount, _init: false } }];

// dlqw004-parse-and-build (PRO-215)
// dispatch_dlq.jsonl does not currently carry issue_identifier, so fall back
// to trace_id to keep the notification actionable without reading other files.
function esc(s) {
  return String(s == null ? 'unknown' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const rawRow = $input.item.json.new_rows;
let row;
try {
  row = JSON.parse(rawRow);
} catch (e) {
  row = {
    issue_identifier: null,
    trace_id: null,
    error_class: 'invalid_json',
    timestamp: new Date().toISOString()
  };
}

const issueIdentifier = row.issue_identifier || row.trace_id || row.prompt_path || row.worker || 'unknown';
const text = '\u26A0\uFE0F Dispatch failed \u2014 ' + esc(issueIdentifier)
  + '\nError: ' + esc(row.error_class || 'unknown')
  + '\nTrace: ' + esc(row.trace_id || 'unknown')
  + '\nTime: ' + esc(row.timestamp || 'unknown');

return {
  json: {
    ...row,
    issue_identifier: issueIdentifier,
    telegram_text: text
  }
};
